<script setup>
import { Link, router } from '@inertiajs/vue3';
import { reactive, ref } from 'vue';
import AssessmentLayout from './AssessmentLayout.vue';
const props = defineProps({ logs: Object, filters: Object, stats: Object });
const form = reactive({ status: props.filters?.status || '', from: props.filters?.from || '', to: props.filters?.to || '', search: props.filters?.search || '' });
const expanded = ref(null);
const apply = () => router.get(route('redesign.error-logs'), { ...form }, { preserveState: true });
const reset = () => { Object.assign(form, { status: '', from: '', to: '', search: '' }); apply(); };
</script>
<template><AssessmentLayout title="Server error logs" subtitle="Pemantauan exception, request, dan trace server." breadcrumb="Operasional"><div class="tabs"><button v-for="tab in [['','Semua'],['500','500'],['422','422']]" :key="tab[0]" type="button" class="secondary" :aria-pressed="form.status===tab[0]" @click="form.status=tab[0];apply()">{{ tab[1] }}</button></div><form class="panel" style="margin-bottom:20px" @submit.prevent="apply"><div class="fields"><label>Cari pesan, URL, atau trace<input v-model="form.search" /></label><label>Status HTTP<input v-model="form.status" type="number" min="400" max="599" placeholder="Semua status" /></label><label>Dari tanggal<input v-model="form.from" type="date" :max="form.to || undefined" /></label><label>Sampai tanggal<input v-model="form.to" type="date" :min="form.from || undefined" /></label></div><div class="actions"><button class="primary">Terapkan filter</button><button class="secondary" type="button" @click="reset">Reset</button></div></form><section class="panel"><h2>Server error logs</h2><p class="muted">{{ logs.total }} log · {{ stats.last_24h }} dalam 24 jam</p><div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Status</th><th>Exception</th><th>Pesan</th><th>File / baris</th><th>Aksi</th></tr></thead><tbody><template v-for="log in logs.data" :key="log.id"><tr><td>{{ log.created_at?.slice(0,16).replace('T',' ') }}</td><td>{{ log.status_code }}</td><td>{{ log.exception_class?.split('\\').pop() }}</td><td>{{ log.message }}</td><td>{{ log.file?.split(/[\\/]/).pop() }} : {{ log.line }}</td><td><button type="button" class="secondary" :aria-expanded="expanded===log.id" @click="expanded=expanded===log.id?null:log.id">{{ expanded===log.id?'Tutup':'Lihat trace' }}</button></td></tr><tr v-if="expanded===log.id"><td colspan="6"><div class="trace"><dl><dt>Trace ID</dt><dd>{{ log.trace_id || '—' }}</dd><dt>Request</dt><dd>{{ log.method }} {{ log.url }}</dd><dt>Pengguna / IP</dt><dd>{{ log.user_id || '—' }} / {{ log.ip || '—' }}</dd></dl><pre>{{ JSON.stringify(log.context || {}, null, 2) }}</pre></div></td></tr></template><tr v-if="!logs.data?.length"><td colspan="6">Tidak ada log pada filter ini.</td></tr></tbody></table></div><div class="pager"><Link v-for="(link,index) in logs.links" :key="index" :href="link.url||'#'" :class="{active:link.active,disabled:!link.url}" v-html="link.label" /></div></section></AssessmentLayout></template>
<style scoped>.trace{background:#f3f7f7;border-radius:8px;padding:14px;max-width:100%;overflow:auto}.trace dl{display:grid;grid-template-columns:110px 1fr;gap:6px}.trace dt{font-weight:700}.trace dd{margin:0;overflow-wrap:anywhere}.trace pre{max-height:300px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere}</style>
